// Normalizes one intake submission. Keys on QUESTION TEXT, never column index --
// Google Forms appends new questions to the far right of the sheet and leaves
// deleted questions' columns in place, so position is not stable.

const Q = {
  SPANISH: {
    email: 'Correo electrónico',
    name:  'Nombre y apellido completo',
    phone: 'Teléfono celular (con código de país)',
    hours: '¿Cuántas horas por semana tienes disponibles para entrenar?',
    week:  'Cuéntame cómo sería tu semana ideal de entrenamiento',
    sport: '¿Cuál es la disciplina principal que entrenarás con nosotros?',
  },
  ENGLISH: {
    email: 'Email address',
    name:  'Full name',
    phone: 'Mobile Phone (with country code)',
    hours: 'How many hours per week do you have available to train?',
    week:  'Tell me what your ideal training week would look like',
    sport: 'What is the primary discipline or the one you want to train for with us?',
  },
};

// Tolerates trailing spaces and case drift in question text -- "Disponibilidad
// semanal [Sábado ]" in the live form already has one.
function pick(answers, label) {
  if (label && answers[label] !== undefined) return answers[label];
  const want = String(label || '').trim().toLowerCase();
  for (const k of Object.keys(answers)) {
    if (k.trim().toLowerCase() === want) return answers[k];
  }
  return '';
}

return $input.all().map(item => {
  const b = item.json.body || item.json;
  const answers = b.answers || {};
  const lang = Q[b.form_language] ? b.form_language : 'SPANISH';
  const q = Q[lang];

  // Fuzzy fallback for the sport question: its wording differs slightly between
  // the two forms and is the most likely to be reworded.
  let sport = pick(answers, q.sport);
  if (!sport) {
    const k = Object.keys(answers).find(k =>
      /disciplina principal|primary discipline/i.test(k));
    if (k) sport = answers[k];
  }

  const email = String(pick(answers, q.email) || '').trim();

  return { json: {
    ok: Boolean(email),
    form_language: lang,
    email,
    full_name: pick(answers, q.name),
    phone: pick(answers, q.phone),
    sport,
    hours_available: pick(answers, q.hours),
    ideal_week: pick(answers, q.week),
    answer_count: Object.keys(answers).length,
    raw: JSON.stringify({ form_language: lang, sheet_name: b.sheet_name || '',
                          submitted_at: b.submitted_at || '', answers }),
  }};
});

